{
  "critique": [
    {
      "design": "r1A",
      "good": "The product fields, quantity and price fit within the initial viewport. Headers and compact values stay intact, and the two-line SKU entries give the rows a consistent rhythm.",
      "problems": "Readers must scroll a long way to reach tax, total and fulfillment details. The SKU wraps, so comparing the full identifiers takes more effort.",
      "cause": "The 99px SKU column permits wrapping at hyphens. The 102px warehouse and 180px tracking columns preserve long words and identifiers but contribute to the 763px overall width."
    },
    {
      "design": "r1B",
      "good": "Like r1A, it keeps headers and compact values intact while showing the product fields through price in the initial viewport.",
      "problems": "It has the same long horizontal scroll and wrapped SKU values as r1A; it offers no visible alternative.",
      "cause": "Its column widths are identical to r1A's."
    }
  ],
  "done": false,
  "designs": [
    {
      "name": "sku-one-line",
      "widths": [38, 157, 61, 52, 47, 62, 53, 68, 102, 180],
      "change": "Give SKU its full one-line width to make identifiers easier to scan and compare. Warehouse values may still wrap; the wider SKU also pushes price beyond the initial viewport and increases scrolling."
    },
    {
      "name": "warehouse-one-line",
      "widths": [38, 99, 61, 52, 47, 62, 53, 68, 143, 180],
      "change": "Keep the initial product-through-price view and natural SKU wrapping, while giving warehouse values room on one line. This makes fulfillment locations easier to scan at the cost of additional horizontal scrolling."
    },
    {
      "name": "all-values-one-line",
      "widths": [38, 157, 61, 52, 47, 62, 53, 68, 143, 180],
      "change": "Give both SKU and warehouse their full one-line widths. This tests a compact, single-line row rhythm and easier identifier comparison against the substantially longer horizontal scroll."
    }
  ]
}
